{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C02", "C16", "C25", "C26", "C01", "C07", "C06"],
  "contradictory_card_ids": ["C56", "C65", "C57", "C58", "C55", "C61"],
  "prediction_basis_card_ids": ["C02", "C16", "C25", "C26"],
  "claims": [
    {
      "claim": "Directly measured oral bioavailability in humans/rats for related phenolic natural products is consistently below 20%: chrysin <1% (C02) and predicted 0.003–0.02% (C16); acacetin poor due to glucuronidation and BCRP/MRP2 efflux (C25); 7,8-benzoflavone 13.2% (C26); anthocyanins 0.14–0.48% (C01, C03, C05, C10, C11, C12, C17); curcumin poor (C07, C13, C14, C19); flavonolignans very low by CL/F (C06, C08, C09, C15, C18).",
      "card_ids": ["C02", "C16", "C25", "C26", "C01", "C03", "C05", "C10", "C11", "C12", "C17", "C07", "C13", "C14", "C19", "C06", "C08", "C09", "C15", "C18"]
    },
    {
      "claim": "L5 gut-wall transport records are for other molecules and show passive diffusion/no efflux (decursin efflux ratio 1.0, C56/C65; formononetin passive diffusion, C57; calycosin passive diffusion, C58; prunetin/biochanin A moderate-high permeability, C55/C61), but they do not provide scopoletin-specific systemic F or intestinal metabolism data; permeability alone does not establish F >= 20%.",
      "card_ids": ["C56", "C65", "C57", "C58", "C55", "C61"]
    },
    {
      "claim": "No direct scopoletin-specific oral bioavailability or matched oral/IV record is available; the low prediction rests on transferable low-F outcomes from related phenolic natural products, and L5 does not overturn them.",
      "card_ids": ["C02", "C16", "C25", "C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C56", "C65", "C57", "C58", "C55", "C61"]
    }
  ],
  "evidence_gaps": [
    "No direct scopoletin-specific oral bioavailability or matched oral/IV pharmacokinetic record is available.",
    "No direct measurement of scopoletin first-pass glucuronidation/sulfation, demethylation, or efflux is available.",
    "L5 records are for other molecules (calycosin, baicalein, prunetin, glycitein, biochanin A, wogonin, decursin, scutellarein, jatrorrhizine, formononetin), not scopoletin.",
    "Structural transfer from flavonoids/curcumin to scopoletin is limited by differences in size, polarity, and metabolic liabilities; no coumarin-specific F data are available."
  ],
  "decision_summary": "L1/L2 provide consistent direct low-F measurements for related phenolic natural products (chrysin <1%, anthocyanins 0.14–0.48%, curcumin poor, flavonolignans very low, acacetin poor, 7,8-benzoflavone 13.2%). L5 adds gut-wall transport records for other molecules showing passive diffusion/no efflux, which support the absorption component but do not provide scopoletin-specific systemic F or address first-pass metabolism. The new evidence does not overturn the transferable low-F basis, so the prediction remains low with moderate confidence."
}

